beforeSaveCustomScript:
if (bySystem) {
    description = 'Problema asociado con el equipo no tiene nada que ver con un ataque real';
}
if (urgent && entity\isAttributeChanged('urgent')) {

    record\create(
        'Task',
        'name', 'Revisión urgente de incidente',
        'description', description,
        'status', 'Not Started',
        'assignedUserId', assignedUserId
    );

}
if (!entity\isNew() && entity\isAttributeChanged('actionsToken') && actionsToken) {

    record\create(
        'Task',
        'name', 'Acción tomada requerida en incidente',
        'description', string\concatenate('Revisar acciones tomadas del incidente: ', name),
        'status', 'Not Started',
        'assignedUserId', assignedUserId
    );

}
